-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere characters.sql, characters_full.sql y characters_genshin_missing.sql.
--
-- Materiales de ascension de los personajes de Genshin Impact: lo que cuesta
-- cada subida de limite de nivel, del 20 al 90, con su icono, su cantidad y
-- la Mora. Mismo formato que la columna ascension de Honkai.
--
-- Fuente: Yatta (gi.yatta.moe), que saca los datos del propio juego y ya los
-- trae en espanol. El ID de cada personaje se ha tomado de su icono y, para
-- los 10 cuyo icono viene de la wiki, de su nombre.
--
-- Solo son updates: volver a ejecutarlo no duplica nada.
--
-- Generado el 2026-09-11. Se consiguieron para 119 de 119 personajes.

alter table public.characters add column if not exists ascension jsonb;

